use std::{error::Error, fmt};

/// Error returned by semaphore operations.
///
/// This type wraps the underlying operating system error generated by the
/// native semaphore implementation.
///
/// The original operating system error can be inspected through
/// [`raw_os_error`](Self::raw_os_error),
/// [`kind`](Self::kind) or
/// [`as_io_error`](Self::as_io_error).
#[derive(Debug)]
pub struct SemaphoreError {
    inner: std::io::Error,
}

impl SemaphoreError {
    /// Creates a [`SemaphoreError`] from the last operating system error.
    ///
    /// This method is intended for use by the platform-specific
    /// implementations.
    pub(crate) fn last_os_error() -> Self {
        Self {
            inner: std::io::Error::last_os_error(),
        }
    }

    /// Returns the underlying [`std::io::Error`].
    pub fn as_io_error(&self) -> &std::io::Error {
        &self.inner
    }

    /// Returns the raw operating system error code, if available.
    ///
    /// Examples include:
    ///
    /// - Linux: `errno`
    /// - Windows: Win32 error code returned by `GetLastError()`
    pub fn raw_os_error(&self) -> Option<i32> {
        self.inner.raw_os_error()
    }

    /// Returns the corresponding [`std::io::ErrorKind`].
    pub fn kind(&self) -> std::io::ErrorKind {
        self.inner.kind()
    }
}

impl fmt::Display for SemaphoreError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.inner.fmt(f)
    }
}

impl Error for SemaphoreError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        Some(&self.inner)
    }
}

impl From<std::io::Error> for SemaphoreError {
    fn from(inner: std::io::Error) -> Self {
        Self { inner }
    }
}

impl AsRef<std::io::Error> for SemaphoreError {
    fn as_ref(&self) -> &std::io::Error {
        &self.inner
    }
}
